use std::{collections::{HashMap, VecDeque}, fs::{self, File, OpenOptions}, io::{self, BufReader, BufWriter, Read, Seek, SeekFrom, Write}, path::{Path, PathBuf}, time::UNIX_EPOCH};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

const CHUNK: usize = 256 * 1024;
struct Pipe(BufWriter<io::Stdout>);
impl Pipe {
    fn send(&mut self, kind: u8, ch: u64, data: &[u8]) { let mut h = [0u8;13]; h[..4].copy_from_slice(&(data.len() as u32).to_le_bytes()); h[4]=kind; h[5..].copy_from_slice(&ch.to_le_bytes()); let _ = self.0.write_all(&h).and_then(|_| self.0.write_all(data)).and_then(|_| self.0.flush()); }
    fn json(&mut self, ch:u64, v:Value) { self.send(3,ch,v.to_string().as_bytes()); }
}
fn hash(p:&Path)->io::Result<String> { let mut f=File::open(p)?; let mut h=Sha256::new(); let mut b=[0u8;65536]; loop { let n=f.read(&mut b)?; if n==0 { break } h.update(&b[..n]); } Ok(format!("{:x}",h.finalize())) }
fn mtime(m:&fs::Metadata)->u128 { m.modified().ok().and_then(|v|v.duration_since(UNIX_EPOCH).ok()).map_or(0,|v|v.as_nanos()) }
fn safe(p:&str)->bool { !p.is_empty() && p.split('/').all(|v| !v.is_empty() && !v.starts_with('.') && !v.contains(['\\',':','\0'])) }
fn walk(root:&Path, dir:&Path, out:&mut Vec<Value>)->io::Result<()> { for e in fs::read_dir(dir)? { let e=e?; let name=e.file_name(); if name.to_string_lossy().starts_with('.') {continue} let ty=e.file_type()?; let p=e.path(); if ty.is_dir() {walk(root,&p,out)?} else if ty.is_file() { let m=e.metadata()?; let rel=p.strip_prefix(root).unwrap().components().map(|x|x.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/"); out.push(json!({"path":rel,"size":m.len(),"mtime":mtime(&m).to_string(),"sha256":hash(&p)?})); } } Ok(()) }
fn plan(root:&Path, v:&Value)->(&'static str,u64) { let p=v["path"].as_str().unwrap_or(""); let size=v["size"].as_u64().unwrap_or(0); let target=root.join(p); if fs::metadata(&target).is_ok_and(|m|m.len()==size) && hash(&target).ok().as_deref()==v["sha256"].as_str() { return ("skip",0) } let part=root.join(".peek-sync-part").join(p); if let Ok(m)=fs::metadata(part) { if m.len()<=size {return ("resume",m.len())} } ("fetch",0) }
fn chunk(path:&str, offset:u64, data:&[u8])->Vec<u8> { let h=json!({"path":path,"offset":offset,"len":data.len()}).to_string(); let mut v=(h.len() as u32).to_le_bytes().to_vec(); v.extend_from_slice(h.as_bytes()); v.extend_from_slice(data); v }
fn unchunk(b:&[u8])->Option<(Value,&[u8])> { let n=u32::from_le_bytes(b.get(..4)?.try_into().ok()?) as usize; let end=4usize.checked_add(n)?; let h:Value=serde_json::from_slice(b.get(4..end)?).ok()?; let d=b.get(end..)?; if h["len"].as_u64()? != d.len() as u64 {return None} Some((h,d)) }
fn finish(root:&Path, file:&Value)->io::Result<bool> { let p=file["path"].as_str().unwrap_or(""); let part=root.join(".peek-sync-part").join(p); if hash(&part)? != file["sha256"].as_str().unwrap_or("") { fs::remove_file(part)?; return Ok(false) } OpenOptions::new().write(true).open(&part)?.sync_data()?; let dest=root.join(p); fs::create_dir_all(dest.parent().unwrap())?; fs::rename(part,dest)?; Ok(true) }
struct Sending { path:String, file:File, size:u64, pos:u64, outstanding:VecDeque<u64>, stamp:String }
struct State { index:HashMap<String,Value>, queue:VecDeque<Value>, current:Option<Value>, sending:Option<Sending>, pass:u8, copied:u64, skipped:u64, resumed:u64, bytes:u64, errors:Vec<String>, synced:u64 }
impl State { fn new()->Self { Self {index:HashMap::new(),queue:VecDeque::new(),current:None,sending:None,pass:0,copied:0,skipped:0,resumed:0,bytes:0,errors:vec![],synced:0} } }
fn next(s:&mut State, root:&Path, pipe:&mut Pipe, ch:u64) { while let Some(v)=s.queue.pop_front() { let p=v["path"].as_str().unwrap_or(""); if !safe(p) {s.errors.push(format!("invalid path: {p}"));continue} let (decision,offset)=plan(root,&v); if decision=="skip" {s.skipped+=1;continue} if decision=="resume" && offset>0 {s.resumed+=1} if decision=="fetch" {let _=fs::remove_file(root.join(".peek-sync-part").join(p));} pipe.json(ch,json!({"t":"want","path":p,"offset":offset})); s.current=Some(v); return } pipe.json(ch,json!({"t":"status","message":"pass finished"})); pipe.json(ch,json!({"t":"done","copied":s.copied,"skipped":s.skipped,"resumed":s.resumed,"bytes":s.bytes,"errors":s.errors})); if s.pass==0 {s.pass=1;pipe.json(ch,json!({"t":"index?"}));} }
fn pump(s:&mut State, root:&Path, window:usize, pipe:&mut Pipe,ch:u64) { if let Some(x)=s.sending.as_mut() { let mut failed=false; while x.outstanding.len()<window && x.pos<x.size { let mut b=vec![0; CHUNK.min((x.size-x.pos) as usize)]; match x.file.read_exact(&mut b) { Ok(())=>{}, Err(_)=>{failed=true;break} } let offset=x.pos; x.pos+=b.len() as u64; x.outstanding.push_back(x.pos); pipe.send(4,ch,&chunk(&x.path,offset,&b)); } if failed || (x.pos==x.size && x.outstanding.is_empty()) { let changed=failed || fs::metadata(root.join(&x.path)).map_or(true,|m|m.len()!=x.size || mtime(&m).to_string()!=x.stamp); pipe.json(ch,json!({"t":if changed {"changed"} else {"end"},"path":x.path})); s.sending=None; } } }
pub fn run() { let settings:Value=std::env::var("PEEK_SETTINGS").ok().and_then(|v|serde_json::from_str(&v).ok()).unwrap_or(json!({})); let send=PathBuf::from(settings["send"].as_str().unwrap_or("")); let recv=PathBuf::from(settings["receive"].as_str().unwrap_or("")); let source=!settings["send"].as_str().unwrap_or("").is_empty(); let window=settings["window"].as_str().unwrap_or("8").parse::<usize>().unwrap_or(8).max(1); let mut pipe=Pipe(BufWriter::new(io::stdout())); let page=std::env::current_dir().unwrap().join("page"); pipe.send(7,0,json!({"places":[],"page":page}).to_string().as_bytes()); let mut input=BufReader::new(io::stdin().lock()); let mut states:HashMap<u64,State>=HashMap::new(); loop { let mut h=[0u8;13]; if input.read_exact(&mut h).is_err(){break} let n=u32::from_le_bytes(h[..4].try_into().unwrap()) as usize; let kind=h[4]; let ch=u64::from_le_bytes(h[5..].try_into().unwrap()); if n>16*1024*1024 {break} let mut b=vec![0;n]; if input.read_exact(&mut b).is_err(){break} if kind==1 { states.insert(ch,State::new()); pipe.json(ch,json!({"t":"hello","role":if source {"source"} else {"destination"}})); pipe.json(ch,json!({"t":"status","message":"channel opened"})); if !source {pipe.json(ch,json!({"t":"index?"}));} continue } if kind==2 {states.remove(&ch);continue} let Some(s)=states.get_mut(&ch) else {continue}; if kind==4 && !source { if let Some((header,data))=unchunk(&b) { let p=header["path"].as_str().unwrap_or(""); let off=header["offset"].as_u64().unwrap_or(u64::MAX); if s.current.as_ref().and_then(|v|v["path"].as_str())!=Some(p) || !safe(p) {continue} let part=recv.join(".peek-sync-part").join(p); let result=(||->io::Result<()> {fs::create_dir_all(part.parent().unwrap())?; let mut f=OpenOptions::new().create(true).append(true).open(&part)?; if f.metadata()?.len()!=off {return Err(io::Error::other("unexpected offset"))} f.write_all(data)?; s.synced+=data.len() as u64; if s.synced>=8*1024*1024 {f.sync_data()?;s.synced=0} Ok(())})(); if let Err(e)=result {s.errors.push(e.to_string());continue} s.bytes+=data.len() as u64; pipe.json(ch,json!({"t":"ack","path":p,"offset":off+data.len() as u64})); } continue } if kind!=3 {continue} let Ok(v)=serde_json::from_slice::<Value>(&b) else {continue}; match v["t"].as_str().unwrap_or("") { "index?" if source => {pipe.json(ch,json!({"t":"status","message":"indexing"})); let mut files=vec![]; match walk(&send,&send,&mut files) {Ok(())=>{s.index=files.iter().map(|f|(f["path"].as_str().unwrap().to_string(),f.clone())).collect();pipe.json(ch,json!({"t":"index","files":files}));},Err(e)=>pipe.json(ch,json!({"t":"status","error":e.to_string()}))}}, "index" if !source => {s.queue=v["files"].as_array().cloned().unwrap_or_default().into(); next(s,&recv,&mut pipe,ch)}, "want" if source => {let p=v["path"].as_str().unwrap_or(""); let off=v["offset"].as_u64().unwrap_or(0); if let Some(f)=s.index.get(p) { let size=f["size"].as_u64().unwrap_or(0); let stamp=f["mtime"].as_str().unwrap_or("").to_string(); if !safe(p) || off>size || fs::metadata(send.join(p)).map_or(true,|m|m.len()!=size || mtime(&m).to_string()!=stamp) {pipe.json(ch,json!({"t":"changed","path":p}));} else if let Ok(mut file)=File::open(send.join(p)) {if file.seek(SeekFrom::Start(off)).is_ok() {s.sending=Some(Sending {path:p.into(),file,size,pos:off,outstanding:VecDeque::new(),stamp});pump(s,&send,window,&mut pipe,ch)}} }}, "ack" if source => {if let Some(x)=s.sending.as_mut() { if v["path"].as_str()==Some(&x.path) && x.outstanding.front().copied()==v["offset"].as_u64() {x.outstanding.pop_front();} } pump(s,&send,window,&mut pipe,ch)}, "changed" if !source => {if let Some(f)=s.current.take() {let p=f["path"].as_str().unwrap_or(""); let _=fs::remove_file(recv.join(".peek-sync-part").join(p));} next(s,&recv,&mut pipe,ch)}, "end" if !source => {if let Some(f)=s.current.take() {let p=f["path"].as_str().unwrap_or(""); if v["path"].as_str()==Some(p) {let part=recv.join(".peek-sync-part").join(p); if f["size"].as_u64()==Some(0) {let _=fs::create_dir_all(part.parent().unwrap());let _=File::create(&part);} match finish(&recv,&f) {Ok(true)=>s.copied+=1,Ok(false)=>s.errors.push(format!("hash mismatch: {p}")),Err(e)=>s.errors.push(format!("{p}: {e}"))} }} next(s,&recv,&mut pipe,ch)}, _=>{} } } }
#[cfg(test)] mod tests { use super::*; fn temp(name:&str)->PathBuf {let p=std::env::temp_dir().join(format!("peek-sync-test-{}-{name}",std::process::id()));let _=fs::remove_dir_all(&p);fs::create_dir_all(&p).unwrap();p} #[test] fn decisions(){let p=temp("plan");let f=json!({"path":"a","size":1,"sha256":format!("{:x}",Sha256::digest(b"x"))}); assert_eq!(plan(&p,&f).0,"fetch");fs::create_dir_all(p.join(".peek-sync-part")).unwrap();fs::write(p.join(".peek-sync-part/a"),b"x").unwrap();assert_eq!(plan(&p,&f), ("resume",1));fs::write(p.join("a"),b"x").unwrap();assert_eq!(plan(&p,&f).0,"skip");fs::remove_dir_all(p).unwrap();} #[test] fn headers(){let b=chunk("日本語",42,b"hello");let (h,d)=unchunk(&b).unwrap();assert_eq!(h["offset"],42);assert_eq!(d,b"hello");} #[test] fn mismatch(){let p=temp("mismatch");fs::create_dir_all(p.join(".peek-sync-part")).unwrap();fs::write(p.join(".peek-sync-part/a"),b"bad").unwrap();fs::write(p.join("a"),b"old").unwrap();assert!(!finish(&p,&json!({"path":"a","sha256":"wrong"})).unwrap());assert_eq!(fs::read(p.join("a")).unwrap(),b"old");assert!(!p.join(".peek-sync-part/a").exists());fs::remove_dir_all(p).unwrap();} }
